CREATE DATABASE IF NOT EXISTS sunrise_dental_clinic CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sunrise_dental_clinic;
CREATE TABLE IF NOT EXISTS users(user_id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('ADMIN','STAFF') NOT NULL DEFAULT 'STAFF',full_name VARCHAR(100) NOT NULL,email VARCHAR(120),is_active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS patients(patient_id INT AUTO_INCREMENT PRIMARY KEY,appointment_number VARCHAR(30) UNIQUE NOT NULL,full_name VARCHAR(100) NOT NULL,address VARCHAR(255) NOT NULL,contact_number VARCHAR(20) NOT NULL,email VARCHAR(120),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_patient_contact(contact_number));
CREATE TABLE IF NOT EXISTS dentists(dentist_id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,specialization VARCHAR(100) NOT NULL,contact_number VARCHAR(20),is_available BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS treatments(treatment_id INT AUTO_INCREMENT PRIMARY KEY,treatment_name VARCHAR(100) UNIQUE NOT NULL,base_cost DECIMAL(10,2) NOT NULL,description VARCHAR(255),is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS appointments(appointment_id INT AUTO_INCREMENT PRIMARY KEY,appointment_number VARCHAR(30) UNIQUE NOT NULL,patient_id INT NOT NULL,dentist_id INT NOT NULL,treatment_id INT NOT NULL,appointment_date DATE NOT NULL,appointment_time TIME NOT NULL,status ENUM('BOOKED','COMPLETED','CANCELLED') DEFAULT 'BOOKED',created_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(patient_id),FOREIGN KEY(dentist_id) REFERENCES dentists(dentist_id),FOREIGN KEY(treatment_id) REFERENCES treatments(treatment_id),FOREIGN KEY(created_by) REFERENCES users(user_id),INDEX idx_appt_datetime(dentist_id,appointment_date,appointment_time));
CREATE TABLE IF NOT EXISTS bills(bill_id INT AUTO_INCREMENT PRIMARY KEY,appointment_id INT UNIQUE NOT NULL,consultation_fee DECIMAL(10,2) NOT NULL,treatment_cost DECIMAL(10,2) NOT NULL,discount DECIMAL(10,2) DEFAULT 0,total_amount DECIMAL(10,2) NOT NULL,pricing_strategy VARCHAR(100),generated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(appointment_id) REFERENCES appointments(appointment_id));
CREATE TABLE IF NOT EXISTS system_logs(log_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,action VARCHAR(100) NOT NULL,details TEXT,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE SET NULL);
