DROP PROCEDURE IF EXISTS sp_create_appointment//
CREATE PROCEDURE sp_create_appointment(IN p_patient_name VARCHAR(100),IN p_address VARCHAR(255),IN p_contact VARCHAR(20),IN p_email VARCHAR(120),IN p_dentist_id INT,IN p_treatment_id INT,IN p_date DATE,IN p_time TIME,IN p_created_by INT,OUT p_appointment_number VARCHAR(30))
BEGIN DECLARE v_patient_id INT; DECLARE v_number VARCHAR(30); DECLARE v_count INT; SELECT COUNT(*) INTO v_count FROM appointments WHERE dentist_id=p_dentist_id AND appointment_date=p_date AND appointment_time=p_time AND status='BOOKED'; IF v_count>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Dentist already has an appointment at this time'; END IF; SET v_number=CONCAT('APT-',DATE_FORMAT(NOW(),'%Y%m%d'),'-',LPAD(FLOOR(RAND()*100000),5,'0')); INSERT INTO patients(appointment_number,full_name,address,contact_number,email) VALUES(v_number,p_patient_name,p_address,p_contact,p_email); SET v_patient_id=LAST_INSERT_ID(); INSERT INTO appointments(appointment_number,patient_id,dentist_id,treatment_id,appointment_date,appointment_time,created_by) VALUES(v_number,v_patient_id,p_dentist_id,p_treatment_id,p_date,p_time,p_created_by); SET p_appointment_number=v_number; END//
DELIMITER ;
